import React, { useState, useContext, useEffect} from 'react';
import styled from 'styled-components';
import Navbar from './components/Navbar/Navbar';
import Hero from './components/Hero/Hero';
import ProjectsGrid from './components/ProjectsGrid/ProjectsGrid';
import Footer from './components/Footer/Footer';
import Modal from './components/Modal/Modal';
import { ThemeProvider, ThemeContext } from './ThemeContext';
const AppContainer = styled.div`
  display: flex;
`;

const MainContent = styled.main`
  flex-grow: 1;
  /* Add padding to the top to offset the 70px navbar */
  padding: 70px 4rem 2rem 4rem; 

  @media (max-width: 768px) {
    padding: 70px 1.5rem 1rem 1.5rem;
  }
`;
function AppContent() { // We extract the main app content to a new component
  const [modalContent, setModalContent] = useState(null);
  const { theme } = useContext(ThemeContext); // Get the theme

  useEffect(() => {
    document.body.setAttribute('data-theme', theme);
  }, [theme]);



  return (
    <AppContainer>
      <Navbar />
      <MainContent>
        <Hero onInterestClick={openModal} />
        {/* ... etc */}
      </MainContent>
      {/* ... modal component */}
    </AppContainer>
  );
}
function App() {
